#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define N 5
#define MAXQ (N * N)
static const int dr[4] = { -1, 1, 0, 0 };
static const int dc[4] = { 0, 0, -1, 1 };

int main(int argc, char *argv[])
{
    if (argc != 5) {
        puts("INVALID_CELL");
        return 0;
    }
    int sr = strtol(argv[1], NULL, 10);
    int sc = strtol(argv[2], NULL, 10);
    int tr = strtol(argv[3], NULL, 10);
    int tc = strtol(argv[4], NULL, 10);
    if (sr < 0 || sr >= N || sc < 0 || sc >= N || tr < 0 || tr >= N || tc < 0 || tc >= N) {
        puts("INVALID_CELL");
        return 0;
    }
    char grid[N][N];
    for (int i = 0; i < N; ++i) {
        char line[64];
        if (!fgets(line, sizeof(line), stdin)) {
            for (int j = 0; j < N; ++j) grid[i][j] = '.';
            continue;
        }
        for (int j = 0; j < N; ++j) {
            grid[i][j] = (line[j] != '\0' && line[j] != '\n') ? line[j] : '.';
        }
    }
    bool visited[N][N] = { { false } };
    int dist[N][N] = { { 0 } };
    int qrow[MAXQ];
    int qcol[MAXQ];
    int head = 0, tail = 0;
    visited[sr][sc] = true;
    dist[sr][sc] = 0;
    qrow[tail] = sr;
    qcol[tail] = sc;
    ++tail;
    bool reached = false;
    while (head < tail) {
        int r = qrow[head];
        int c = qcol[head];
        ++head;
        if (r == tr && c == tc) { reached = true; break; }
        for (int d = 0; d < 4; ++d) {
            int nr = r + dr[d];
            int nc = c + dc[d];
            if (nr < 0 || nr >= N || nc < 0 || nc >= N) continue;
            if (visited[nr][nc]) continue;
            if (grid[nr][nc] == '#') continue;
            visited[nr][nc] = true;
            dist[nr][nc] = dist[r][c] + 1;
            qrow[tail] = nr;
            qcol[tail] = nc;
            ++tail;
        }
    }
    if (reached) {
        printf("dist=%d\n", dist[tr][tc]);
    } else {
        puts("UNREACHABLE");
    }
    return 0;
}
